exec(open('analysis/fit_camera.py').read().split('p=[3.3')[0])
p=np.array(list(json.load(open('analysis/camera.json')).values()));cam=p[2:5];target=p[5:8];b=cam-target;b/=np.linalg.norm(b);r=np.cross([0,1,0],b);r/=np.linalg.norm(r);u=np.cross(b,r)
def pr(x,y,z):
 q=(np.array([x,y,z])-cam)@np.array([r,u,b]).T
 return np.array([240-p[8]*q[0]/q[2],180+p[8]*q[1]/q[2]])
for x in [-4.3,4.6]:
 for z in [-5.4,5.9]:print(x,z,pr(x,-.092,z))
# Unproject pixels onto the page plane.
for pix in [[198,58],[118,109],[220,178],[252,245],[270,313],[110,208],[342,127]]:
 v=r*(pix[0]-240)/p[8]+u*(180-pix[1])/p[8]-b
 P=cam+v*((-.092-cam[1])/v[1]);print(pix,'=>',P)
PY"
